        .section h3 { color: #4a90a4; margin: 20px 0 10px; }
        p { margin-bottom: 15px; text-align: justify; }
        .chart-container { text-align: center; margin: 20px 0; }
        .chart-container img { max-width: 100%; border-radius: 8px; }
        .chart-caption { font-size: 0.85em; color: #666; margin-top: 8px; }
        table { width: 100%; border-collapse: collapse; margin: 20px 0; }
        th { background: #1e3a5f; color: white; padding: 12px; text-align: left; }
        td { padding: 10px; border-bottom: 1px solid #eee; }
        tr:hover { background: #f8f9fa; }
        .highlight { background: #c9a227; color: white; padding: 15px; border-radius: 5px; margin: 15px 0; }
        .callout { background: #e8f4f8; border-left: 4px solid #4a90a4; padding: 15px; margin: 15px 0; }
        .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
        @media (max-width: 768px) { .two-col { grid-template-columns: 1fr; } }
        .footer { text-align: center; padding: 20px; color: #666; font-size: 0.85em; }
        .warning { color: #c0392b; font-weight: bold; }
    </style>
</head>
